function actual(row) {
  if (phase2Cases.has(row.id)) return phase2Cases.get(row.id).actual;
  if (row.blocked) return `Not executed. ${row.blocked}`;
  if (!verified || !row.evidence) return 'Not executed as a complete current case. Source inspection is not functional verification; follow steps before updating status.';
  if (row.evidence==='SOURCE') return 'Source inspected: listed brand/footer/decorative elements have no interactive handler or link.';
  if (row.evidence.startsWith('API')) return 'Relevant current isolated API/PostgreSQL regression passed; Auth/Storage/AI boundaries simulated. No live-provider assertion.';
  if (row.evidence==='W1') return 'Reproduced empty collections before fix; final four-width keyboard regression passed with saved/reopened Work, Daily.';
  if (row.evidence==='W2') return 'Reproduced stale replacement before fix; final four-width regression passed with cancelled replacement and working selection.';
  if (row.id.startsWith('CL-CAT-')) return `Category activation showed the expected fixture matches or zero cards; returning to All pieces recovered the grid. This does not prove positive ownership data in every category.`;
  return `${observations[row.id] || 'Primary named scenario passed its current assertions.'} Automated fixture evidence only; extra limits/options/manual variants are not promoted.`;
}
const counts = Object.fromEntries(['Not tested','Passed','Failed','Blocked'].map(s=>[s,rows.filter(r=>state(r)===s).length]));
let out = `# Workshop 5.4 Step 1 — systematic testing checklist\n\nGenerated from the inspected current React pages/components, shared contracts, API/worker code and existing test assertions. The older [update-only checklist](workshop-5.4-testing-checklist.md) is historical context, not proof of this run.\n\n**Scope:** every implemented page, entry point, button/link/icon control, form field, native menu option family, conditional dialog/action and meaningful read/write/retry/cancel workflow found in source. Repeated card/entry/component controls are parameterized by their ID/label; test each repeated instance with disposable data. Static branding and decorative illustrations are inventoried separately. There are no implemented password-reset/account-deletion menus, checkout, weather or deployment controls to invent.\n\n**Status semantics:** Passed applies only to the stated steps and evidence boundary, not to all listed candidate inputs. Every additional boundary/fault/keyboard variant is queued in VAL/AX and option cases, and remains Not tested unless explicitly exercised. Blocked identifies an unmet prerequisite and the action needed. No manual UI, inbox, device or provider check is marked Passed. A confirmed defect can be fixed/retested while its broader control matrix remains Not tested; see [bug log](workshop-5-4-bug-log.md).\n\n**Current inventory:** ${rows.length} cases — ${counts.Passed} Passed; ${counts['Not tested']} Not tested; ${counts.Failed} Failed; ${counts.Blocked} Blocked. ${verified?'This assignment’s final automated results are in [the sanitized run record](workshop-5-4-results.json).':'No current run has yet been used to promote cases.'}\n\n**Prerequisites and safety:** run isolated tests on port5174, never against personal records. For manual work use an account you control and uniquely named W54 TEST records; preserve all existing records. Refresh before retrying a timed-out write. Fixture persistence is in-memory backend persistence across browser reload, not a live Supabase result. Registration/inbox/provider/physical-device cases require the stated separate exercise. The Step1 live checks remain historical; this next phase has a separately labeled fresh live artifact. This audit does not assert that your configured credentials are missing; Blocked live cases need the stated separate controlled exercise. Repeat shared metadata fields in every hosting form, not just one instance.\n\n**Evidence key:** B0 original protected workflow; B1–B6 feature scenarios in file order; Q1–Q5 quality scenarios; account setup/protection = setup.spec.ts; W1/W2 = workshop.spec.ts; API/SQL = current PGlite/Express/schema suite; SOURCE = read-only implementation inspection. [Browser sources](../tests/browser/), [local regression sources](../tests/), [feature map](feature-inventory.md). No new paid AI or hosted mutation is needed for these isolated checks.\n\n`;
const escape = s => String(s).replaceAll('|','/').replaceAll('\n',' ');
if (phase2) {
  out = out.replace('No manual UI, inbox, device or provider check is marked Passed.','No manual UI, inbox or device check is marked Passed. New live service checks are separately labeled.');
  out = out.replace('This assignment’s final automated results are in [the sanitized run record](workshop-5-4-results.json).','Current evidence is in [next-phase results](workshop-5-4-phase2-results.json); [Step1 results](workshop-5-4-results.json) remain historical.');
  out += `**Next phase:** [Current results](workshop-5-4-phase2-results.json) record 65 isolated API/database/schema tests, 92 fixture Chrome checks and 17 live Supabase checks plus cleanup. New superseding case evidence below comes from these executed checks. The two Step1 fixes remain historical; [new defects and retests](workshop-5-4-bug-log.md) and [read-only security review](workshop-5-4-security-review.md) are separate. Live writes were limited to disposable accounts/records/image; no personal data, hosted configuration, migration or paid OpenAI call was changed/performed. Session expiry, timed URL expiry and browser account switching can be automated and are Not tested, rather than incorrectly requiring human participation.\n\n`;
}
function evidence(row) { return phase2Cases.get(row.id)?.evidence || (verified&&row.evidence ? row.evidence==='SOURCE'?'Manual source inspection; no UI interaction':`${row.evidence}; automated, current run`:'No current execution; manual follow-up required'); }
for (const screen of [...new Set(rows.map(r=>r.screen))]) {
  out += `## ${screen}\n\n| ID / control or feature | Test steps and prerequisites | Expected result | Valid / invalid / boundary inputs | Actual result | Status | Evidence / method |\n| --- | --- | --- | --- | --- | --- | --- |\n`;
  for (const row of rows.filter(r=>r.screen===screen)) out += `| ${escape(row.id)} — ${escape(row.control)} | ${escape(row.steps)} | ${escape(row.expected)} | ${escape(row.inputs)} | ${escape(actual(row))} | ${state(row)} | ${escape(evidence(row))} |\n`;
  out += '\n';
}
out += `## Ordered manual completion walkthrough\n\nUse this order to reach every remaining control; within each screen, execute **each Not tested/Blocked row and its documented input variants**, record actual behavior/evidence, then update that row. Do not mark whole sections Passed from one successful example.\n\n1. **Account:** complete AUTH-06 through AUTH-18 where not passed; use your inbox for confirmation and a disposable account for expired links/session/logout errors. Never record passwords/tokens.\n2. **Shell and Today:** test remaining NAV/SHELL cases, including sidebar and empty-state entry points, toast dismissal/timer, skip link, refresh ordering. Open all four real source links and check publication versus fixed checked dates; no live trend claim.\n3. **Closet and upload:** use W54 TEST records; execute remaining CL/UP/IMG cases, drag/drop/file-picker cancellation, all file bounds, upload cancellation and photo expiry. No private/signed URLs in evidence.\n4. **Review/manual inventory:** execute remaining ITEM/AN and OPT-PAT/UNIT cases. Test every visible-detail checkbox, known/unknown metadata, quantities/packs/collections limits, blank/whitespace values, corrections, proposal reapply and safe deletion/cancel. A real worker/model pass is separate and optional; do not infer accuracy from fixtures.\n5. **Import:** review a small disposable selection; execute remaining IMP and VAL-03/04/05 cases, especially link/skip, filters/details, review reset, preview retry and partial ten-entry batch failure. Do not import your whole inventory as a test.\n6. **Outfits:** execute remaining OUT and VAL-06 through VAL-11 cases. Include manual20 cap, replacement/cancel/remove, all seasons, insufficient/empty/error AI responses, regenerate/save failure and stale edit. Use fixture errors rather than paid requests for failure cases.\n7. **Plans:** execute remaining TPL cases; edit title/occasion/notes/slots, test 0/20 components, unmatched versus resolved transition, save/reopen, and cancel/confirm deletion. Plans must not create owned garments.\n8. **Wear and feedback:** execute remaining HIST/OPT-RATING/VAL-12/13 cases; future/duplicate dates, notes limits, View outfit, garment invalidation and each destructive confirmation. Delete only W54 TEST records.\n9. **Settings and persistence:** execute remaining SET/OPT-GENDER and VAL-14/17 cases, including self-description/reset, empty defaults, all saved record types after reload, failed-save recovery and account switch.\n10. **Cross-cutting:** finish VAL-01/02/15/16/18 and AX-02/03/05/06/07/08/10 across all forms/dialogs. Use keyboard, screen reader, real phones, alternate browsers/zoom and long content. Record unperformed combinations honestly rather than extrapolating from the four-width Chrome suite.\n\nRecord date, device/browser, fixture or live boundary, actual result, issue ID and safe screenshot/report for every manual execution. See [bug log](workshop-5-4-bug-log.md) for confirmed new issues versus prior fixes and unverified concerns.\n`;
fs.writeFileSync('docs/workshop-5-4-testing-checklist.md',out);
